// Shape the failure into a Discord/Slack-compatible payload. Both
// platforms accept a JSON body; Discord reads `content`, Slack reads
// `text`, so we send both keys and either one lights up.
const e = $input.first().json || {};
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const exec = e.execution || {};
const err = (exec.error && (exec.error.message || exec.error.description)) || 'no message';
const node = (exec.lastNodeExecuted) || '(unknown node)';
const url = exec.url || '';
const when = new Date().toISOString();
const msg = `TVF Lead Engine \u2014 HARVEST FAILED\nworkflow: ${wf}\nnode: ${node}\nerror: ${err}\ntime: ${when}${url ? '\n' + url : ''}`;
return [{ json: { content: msg, text: msg } }];
